/* busd-map service worker — generated by scripts/make-tiles.mjs, do not edit public/sw.js directly.
   Precaches the whole tile pyramid + data on install so pan/zoom never hits the network
   after the first visit, and the map works offline. VERSION changes whenever tiles rebuild. */
const VERSION = "__VERSION__";
const CACHE = `busd-map-${VERSION}`;
const MANIFEST = "/map/tiles/manifest.json";
const DATA = ["/data/map.json", "/data/locations.json", "/data/roads.json", "/data/regions.json"];

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    const manifest = await (await fetch(MANIFEST, { cache: "no-store" })).json();
    // app shell: index.html + whatever hashed assets it references
    const html = await (await fetch("/", { cache: "no-store" })).text();
    await cache.put("/", new Response(html, { headers: { "Content-Type": "text/html" } }));
    const assets = [...new Set([...html.matchAll(/(?:src|href)="(\/assets\/[^"]+)"/g)].map((m) => m[1]))];
    const urls = [...assets, ...DATA, ...manifest.tiles];
    // best-effort, in batches; a single failed tile must not block install
    for (let i = 0; i < urls.length; i += 40) {
      await Promise.allSettled(urls.slice(i, i + 40).map((u) => cache.add(u).catch(() => {})));
    }
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) if (k !== CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;
  const p = url.pathname;

  // tiles + hashed assets: cache-first (immutable)
  if (p.startsWith("/map/tiles/") || p.startsWith("/assets/")) {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE);
      const hit = await cache.match(req, { ignoreVary: true });
      if (hit) return hit;
      const res = await fetch(req);
      if (res.ok) cache.put(req, res.clone());
      return res;
    })());
    return;
  }
  // page + data: network-first, cache fallback (offline)
  if (req.mode === "navigate" || p.startsWith("/data/")) {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE);
      try {
        const res = await fetch(req);
        if (res.ok) cache.put(req, res.clone());
        return res;
      } catch {
        return (await cache.match(req, { ignoreSearch: true, ignoreVary: true })) || (req.mode === "navigate" ? cache.match("/", { ignoreVary: true }) : Response.error());
      }
    })());
  }
});
